// === Tab: mySketch.js ===
/*
A submission for the #WCCChallenge theme of Mapping!

This is using a beta build of the upcoming p5.js 2.1 release. It lets you
use for loops and if statements in shaders, and do 3D noise!
*/

let earthShader
let font
let textCam
async function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	font = await loadFont('https://fonts.gstatic.com/s/ebgaramond/v32/SlGFmQSNjdsmc35JDF1K5GRwUjcdlttVFm-rI7e8QI96WamXgXFI.ttf')
	textCam = createCamera()
	earthShader = baseMaterialShader().modify(() => {
		let worldPos = varyingVec3()
		getObjectInputs((inputs) => {
			worldPos = inputs.position.xyz
			return inputs
		})
		getPixelInputs((inputs) => {
			const r = sqrt(pow(worldPos.x, 2) + pow(worldPos.y, 2) + pow(worldPos.z, 2))

			let color = vec3(0.4, 0.2, 0.1)
			let shininess = 0
			if (r > 90) {
				shininess = 0
				const elevation = noise(worldPos * 0.01)
				if (elevation > 0.4) {
					color = mix(
						vec3(0.2, 0.75, 0.25),
						vec3(1, 1, 1),
						smoothstep(0.8, 1, elevation)
					)
				} else if (elevation > 0.25) {
					color = mix(
						vec3(0.9, 0.85, 0.25),
						vec3(0.2, 0.75, 0.25),
						smoothstep(0.25, 0.35, elevation)
					)
				} else {
					shininess = 50
					color = mix(
						vec3(0.05, 0.1, 0.8),
						vec3(0.45, 0.5, 1),
						smoothstep(0, 0.25, elevation)
					)
				}
			} else {
				color += vec3(0.2, 0.2, 0.2) * noise(r * 0.1 + 0.5 * noise(worldPos * 0.004))
			}
			inputs.shininess = shininess
			inputs.color = [color, 1]
			inputs.ambientMaterial = color
			return inputs
		})
	})
}

function draw() {
	background(255)

	scale(max(width, height) / 400)

	orbitControl()

	push()
	const t = millis()
	scale(pow(map(t, 0, 3000, 0, 1, true), 0.5))
	rotateX(PI * 0.05 * sin(t * 0.0003) - PI * 0.1)
	rotateY(pow(map(t, 0, 3000, 0, 1, true), 0.25) * TWO_PI)
	rotateY(PI * 0.2 * sin(t * 0.0004) - PI * 0.1)

	noStroke()
	const geom = csg(() => sphere(100, 20, 12))
		.subtract(() => {
			push()
			translate(80 + 50 * sin(t * 0.001), -80 + 20 * sin(t * 0.0009), 100)
			rotateX(PI * 0.1 * sin(t * 0.00085))
			rotateY(PI * 0.1 * sin(t * 0.00095))
			box(200)
			pop()
		})
		.done()

	lights()
	push()
	shader(earthShader)
	model(geom)
	pop()

	push()
	emissiveMaterial(255, 200, 50)
	sphere(30)
	pop()
	pop()

	push()
	clearDepth()
	setCamera(textCam)
	textFont(font)
	textSize(20)
	textAlign(CENTER, CENTER)
	fill(0)
	text('Fig. 1: Cross-section of a planet', 0, 130)
	pop()

	freeGeometry(geom)
}

